cd "$ARCHON_HORIZON_ROOT" && "$HORIZON_BIN" roadmap list --focus AJCR.w4-rep --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
items = d if isinstance(d,list) else d.get('items',d)
def walk(x):
    if isinstance(x,list):
        for i in x: walk(i)
        return
    if not isinstance(x,dict): return
    if x.get('status') in ('pending','active'):
        print('###',x.get('id'),'|',x.get('status'),'|',x.get('title'))
        for k in ('strategy','notes','description'):
            v=x.get(k)
            if v: print('   ',k,':',str(v)[:900])
    for c in x.get('children',[]) or []: walk(c)
walk(items)
"
